{"query":"
query TargetClinicalContext($ensemblId: String!, $size: Int!) {
  target(ensemblId: $ensemblId) {
    associatedDiseases(page: {index: 0, size: $size}) {
      rows {
        score
        disease {
          id
          name
        }
      }
    }
    drugAndClinicalCandidates {
      rows {
        drug {
          id
          name
        }
      }
    }
  }
}
